package br.tcc.checkout;

import br.tcc.checkout.dto.ItemCarrinho;
import br.tcc.checkout.dto.RequisicaoResumo;
import br.tcc.checkout.dto.RespostaErro;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Arrays;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class CheckoutControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Test
    void testResumoComSucesso() throws Exception {
        RequisicaoResumo requisicao = new RequisicaoResumo();
        requisicao.setItens(Arrays.asList(
                new ItemCarrinho("Camiseta", 79.90, 2, 0.30)
        ));
        requisicao.setModalidadeEntrega("RETIRADA_LOJA");
        requisicao.setFormaPagamento("PIX");

        mockMvc.perform(post("/checkout/resumo")
                .contentType("application/json")
                .content(objectMapper.writeValueAsString(requisicao)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.subtotalProdutos").value(159.80))
                .andExpect(jsonPath("$.frete").value(0.00))
                .andExpect(jsonPath("$.totalFinal").exists());
    }

    @Test
    void testCarrinhoVazio() throws Exception {
        RequisicaoResumo requisicao = new RequisicaoResumo();
        requisicao.setItens(Arrays.asList());
        requisicao.setModalidadeEntrega("RETIRADA_LOJA");
        requisicao.setFormaPagamento("PIX");

        mockMvc.perform(post("/checkout/resumo")
                .contentType("application/json")
                .content(objectMapper.writeValueAsString(requisicao)))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.erro").value("PEDIDO_INVALIDO"));
    }

    @Test
    void testModalidadeInvalida() throws Exception {
        RequisicaoResumo requisicao = new RequisicaoResumo();
        requisicao.setItens(Arrays.asList(
                new ItemCarrinho("Camiseta", 79.90, 1, 0.30)
        ));
        requisicao.setModalidadeEntrega("INEXISTENTE");
        requisicao.setFormaPagamento("PIX");

        mockMvc.perform(post("/checkout/resumo")
                .contentType("application/json")
                .content(objectMapper.writeValueAsString(requisicao)))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.erro").value("MODALIDADE_INVALIDA"));
    }

    @Test
    void testMotoboySobrepeso() throws Exception {
        RequisicaoResumo requisicao = new RequisicaoResumo();
        requisicao.setItens(Arrays.asList(
                new ItemCarrinho("Item Pesado", 100.00, 1, 6.0)
        ));
        requisicao.setModalidadeEntrega("MOTOBOY");
        requisicao.setFormaPagamento("PIX");

        mockMvc.perform(post("/checkout/resumo")
                .contentType("application/json")
                .content(objectMapper.writeValueAsString(requisicao)))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.erro").value("MODALIDADE_INDISPONIVEL"));
    }

    @Test
    void testCupomInvalido() throws Exception {
        RequisicaoResumo requisicao = new RequisicaoResumo();
        requisicao.setItens(Arrays.asList(
                new ItemCarrinho("Camiseta", 79.90, 1, 0.30)
        ));
        requisicao.setModalidadeEntrega("RETIRADA_LOJA");
        requisicao.setCupom("CUPOMINVALIDO");
        requisicao.setFormaPagamento("PIX");

        mockMvc.perform(post("/checkout/resumo")
